The header path (`x-amzn-bedrock-input-token-count`) is the common case on real responses, but no test combines the header with cache tokens in the body. Something like this in `test_invoke_model.py` would cover it:

```python
def test_extract_invoke_model_response_headers_with_cache(tracer_provider) -> None:
    handler = TelemetryHandler(tracer_provider=tracer_provider)
    with handler.inference(provider="aws.bedrock") as invocation:
        extract_invoke_model_response(
            {
                "ResponseMetadata": {
                    "HTTPHeaders": {
                        "x-amzn-bedrock-input-token-count": "10",
                        "x-amzn-bedrock-output-token-count": "5",
                    }
                }
            },
            json.dumps(
                {
                    "usage": {
                        "input_tokens": 10,
                        "output_tokens": 5,
                        "cache_read_input_tokens": 4,
                        "cache_creation_input_tokens": 2,
                    }
                }
            ).encode(),
            invocation,
        )
        assert invocation.input_tokens == 16
        assert invocation.cache_read_input_tokens == 4
        assert invocation.cache_write_input_tokens == 2
```

